<?php
declare(strict_types=1);
function email_safe_message(Throwable $error):string{
 if(get_class($error)===RuntimeException::class||$error instanceof InvalidArgumentException)return $error->getMessage();
 return 'The email action could not be completed. Please try again or contact hosting support.';
}
function email_test_send():never{
 if(admin()['role']!=='admin')abort(403,'Owner access required');
 $to=str('test_recipient',190);if(!filter_var($to,FILTER_VALIDATE_EMAIL)){flash('Enter a valid test recipient email.','error');go('admin/email');}
 if(time()-(int)($_SESSION['smtp_test_last']??0)<60){flash('Please wait one minute before sending another test email.','error');go('admin/email');}
 $_SESSION['smtp_test_last']=time();$ok=false;
 try{smtp_send($to,'36° — Email delivery test',"This is a test email from 36°.\n\nYour saved email configuration submitted this message to the mail server.\n\nTime: ".date('Y-m-d H:i:s T'));$ok=true;$message='The mail server accepted your test email. Check the recipient inbox and spam folder.';}
 catch(Throwable $error){
  $code=(int)$error->getCode();
  if(in_array($code,[334,534,535],true))$message=mail_setting('smtp_auth')==='microsoft'?'Microsoft rejected SMTP authentication. Reconnect the intended mailbox, check SMTP.Send consent and ask your Microsoft 365 administrator whether Authenticated SMTP is enabled for this mailbox.':'SMTP authentication was rejected. Check your username and saved password or app password.';
  elseif(in_array($code,[530,538],true))$message='The mail server requires a different authentication or encryption setup. Check STARTTLS and your selected authentication method.';
  elseif(in_array($code,[550,551,553],true))$message='The mail server rejected the sender or recipient. Check both addresses and any Send As permission.';
  else $message=email_safe_message($error);
 }
 try{mail_put('smtp_test_result',json_encode(['ok'=>$ok,'time'=>time(),'recipient'=>$to,'message'=>$message],JSON_THROW_ON_ERROR));audit($ok?'email.smtp.test.success':'email.smtp.test.failed');}catch(Throwable $ignored){}
 flash($message,$ok?'ok':'error');go('admin/email');
}
