 if(admin()['role']!=='admin')abort(403,'Owner access required');
 admin_page('Email delivery',function(){
  $mode=mail_setting('smtp_auth','password');$connected=false;$callback='';$configError='';
  try{$callback=microsoft_mail_redirect();$tokens=microsoft_mail_tokens();$connected=$tokens&&hash_equals(microsoft_mail_fingerprint(),(string)($tokens['binding']??''));}catch(Throwable $error){$configError='Check the HTTPS website URL in hosting configuration before connecting Microsoft.';}
  $last=json_decode(mail_setting('smtp_test_result','{}'),true)?:[];
 ?><p class="muted">Use password SMTP for your hosting/mail provider, or Microsoft OAuth2 for Outlook and Microsoft 365. Saving applies the configuration; a test checks whether the mail server accepts a message.</p>
 <div class="email-setup-grid"><div><form class="form" method="post" action="/admin/email/settings"><?=token()?><h2>1. Email configuration</h2>
 <label for="email-preset">Microsoft setup shortcut</label><select id="email-preset" data-email-preset><option value="">Keep current values</option value="work">Microsoft 365 — work or school</option><option value="personal">Outlook.com — personal mailbox</option></select>
 <label for="smtp_auth">Authentication method</label><select id="smtp_auth" name="smtp_auth"><option value="password" <?=$mode==='password'?'selected':''?>>SMTP username & password</option><option value="microsoft" <?=$mode==='microsoft'?'selected':''?>>Microsoft modern authentication (OAuth2)</option></select>
 <?php foreach(['smtp_host'=>['SMTP hostname','mail.yourdomain.com'],'smtp_user'=>['SMTP username / mailbox email','you@example.com'],'smtp_from'=>['From email','you@example.com'],'smtp_from_name'=>['Sender name','36°']] as $key=>$field):?><label for="<?=$key?>"><?=$field[0]?></label><input id="<?=$key?>" name="<?=$key?>" value="<?=esc(mail_setting($key,$key==='smtp_from_name'?'36°':''))?>" placeholder="<?=$field[1]?>" <?=$key==='smtp_from'?'type="email" required':($key==='smtp_host'?'required':'')?> maxlength="<?=$key==='smtp_from_name'?'100':'190'?>"><?php endforeach;?>
 <label for="smtp_port">SMTP port</label><input id="smtp_port" name="smtp_port" type="number" min="1" max="65535" value="<?=esc(mail_setting('smtp_port','587'))?>" required><label for="smtp_security">Encryption</label><select id="smtp_security" name="smtp_security"><option value="starttls" <?=mail_setting('smtp_security','starttls')==='starttls'?'selected':''?>>STARTTLS — usually port 587</option><option value="ssl" <?=mail_setting('smtp_security')==='ssl'?'selected':''?>>SSL/TLS — usually port 465</option></select>
 <details class="email-auth-fields" <?=$mode==='password'?'open':''?>><summary>Password SMTP credentials</summary><p class="small muted">For providers that support password-based SMTP. Leave blank to keep the saved password. This is not Microsoft OAuth2.</p><label for="smtp_password">SMTP password <?=mail_secret('smtp_password')!==''?'(saved)':''?></label><input id="smtp_password" name="smtp_password" type="password" autocomplete="new-password" maxlength="4096"></details>
 <details class="email-auth-fields" <?=$mode==='microsoft'?'open':''?>><summary>Microsoft app configuration</summary><p class="small muted">Register a Web application in Microsoft Entra, allow the intended account type, and add delegated Office 365 Exchange Online SMTP.Send permission. Request offline access during sign-in. Your organization may require administrator consent and Authenticated SMTP to be enabled.</p>
 <label for="ms_mail_tenant">Tenant</label><input id="ms_mail_tenant" name="ms_mail_tenant" value="<?=esc(mail_setting('ms_mail_tenant','common'))?>" placeholder="common, organizations, consumers or tenant ID" maxlength="80"><label for="ms_mail_client_id">Application (client) ID</label><input id="ms_mail_client_id" name="ms_mail_client_id" value="<?=esc(mail_setting('ms_mail_client_id'))?>" maxlength="64"><label for="ms_mail_client_secret">Client secret value <?=mail_secret('ms_mail_client_secret')!==''?'(saved — leave blank to keep)':''?></label><input id="ms_mail_client_secret" name="ms_mail_client_secret" type="password" autocomplete="new-password" maxlength="4096"><p class="small muted">Use the secret value, not the secret ID. The platform encrypts credentials and tokens at rest.</p><p>Register this exact Web redirect URI:</p><code><?=esc($callback?:$configError)?></code><p class="small muted">For personal Outlook use smtp-mail.outlook.com; for Microsoft 365 use smtp.office365.com. Both use port 587 and STARTTLS. Use the mailbox email as username. The From address should be that mailbox unless Send As permission is configured.</p></details>
 <button class="btn gold">Save email settings</button></form></div>
 <div><section class="form"><h2>2. Authorize Microsoft</h2><p class="muted">Required only when Microsoft OAuth2 is selected. Sign in as the mailbox configured above.</p><p><strong><?=$connected?'Microsoft authorization saved':'Not connected'?></strong></p><p class="small muted">A saved authorization is not a delivery test. Tokens refresh automatically while consent and app credentials remain valid.</p><form method="post" action="/admin/email/microsoft/connect"><?=token()?><button class="btn gold" <?=$mode!=='microsoft'||!microsoft_mail_configured()?'disabled':''?>><?=$connected?'Reconnect Microsoft':'Connect Microsoft'?></button></form><?php if($connected):?><form method="post" action="/admin/email/microsoft/disconnect"><?=token()?><button class="btn">Disconnect from platform</button></form><?php endif;?><p class="small muted">Changing the mailbox, app, secret, tenant or server requires a new connection. Disconnect removes the saved platform tokens; revoke consent separately in Microsoft if needed.</p></section>
 <section class="form"><h2>3. Send a test email</h2><p class="muted">Save settings first. This sends directly using the saved configuration; no cron worker is needed for a test.</p><form method="post" action="/admin/email/test"><?=token()?><label for="test_recipient">Test recipient</label><input id="test_recipient" name="test_recipient" type="email" value="<?=esc(admin()['email'])?>" maxlength="190" required><button class="btn gold">Send test email</button></form><?php if($last):?><div class="email-test-status" role="status"><strong><?=!empty($last['ok'])?'Last test: server accepted':'Last test: failed'?></strong><p><?=esc((string)($last['message']??''))?></p><small><?=esc(date('d M Y H:i T',(int)($last['time']??0)))?> · <?=esc((string)($last['recipient']??''))?></small></div><?php endif;?></section>
 <details class="form"><summary>Automatic email delivery</summary><p class="muted">Order, booking and recovery emails use the delivery queue. Configure the existing CLI email worker in cPanel Cron Jobs for automatic sending. Microsoft token refresh also runs in that worker.</p><p class="small muted">SMTP acceptance does not guarantee inbox placement. Check spam, sender policies and mailbox restrictions if accepted messages do not arrive.</p></details></div></div>
 <details class="email-queue"><summary>Delivery queue · recent messages</summary><div class="scroll"><table><tr><th>Recipient</th><th>Subject</th><th>Status</th><th>Attempts</th><th>Action</th></tr><?php foreach(all('SELECT id,recipient,subject,status,attempts,last_error FROM email_queue ORDER BY id DESC LIMIT 100') as $email):?><tr><td><?=esc($email['recipient'])?></td><td><?=esc($email['subject'])?></td><td><?=esc($email['status'])?><?php if($email['last_error']):?><small><?=esc($email['last_error'])?></small><?php endif;?></td><td><?=(int)$email['attempts']?></td><td><?php if($email['status']==='failed'):?><form method="post" action="/admin/email/retry"><?=token()?><input type="hidden" name="id" value="<?=(int)$email['id']?>"><button class="btn">Retry</button></form><?php endif;?></td></tr><?php endforeach;?></table></div></details><?php
 });
}
